/*
 * A021916  Decimal expansion of 1/912.
 * https://oeis.org/A021916
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cons
 * Formula:   a(n) = the nth decimal digit of 1/912 (decimal expansion:
 *            0.00109649...). The sequence is generated by the standard
 *            long‑division algorithm for 1 divided by 912
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    // Remainder in the long division, always < 912.
    idx_t r = 1;
    seq_t digit = 0;

    for (idx_t i = 0; i <= n; ++i) {
        r *= 10;               // bring down next zero
        digit = (seq_t)(r / 912); // quotient digit
        r %= 912;              // new remainder
    }
    return digit;
}
